import{Capacitor}from'./capacitor-core.mjs';
import{NativeFamilyBrand,familyIconURL}from'./family-icons.mjs';
export const FAMILY_SITE='https://family-news-app.nimbletide.chatgpt.site';
export function familyAppURL(family){if(!/^[A-Za-z0-9-]{1,40}$/.test(family?.code||''))throw Error('كود العائلة غير صحيح');return FAMILY_SITE+'/family/'+encodeURIComponent(family.code)+'/'}
let installEvent;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installEvent=event});window.addEventListener('appinstalled',()=>{installEvent=null});
export function initFamilyInstall({state,tenants,element:E,button:B,busy,toast}){
 const nav=B('إضافة تطبيق العائلة للشاشة الرئيسية',()=>open(),'text-button');nav.id='family-install-open';nav.hidden=true;document.querySelector('.app-nav').append(nav);
 async function iconData(family){const image=new Image(),url=familyIconURL(family);image.crossOrigin='anonymous';image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,512,512);const scale=Math.min(464/image.naturalWidth,464/image.naturalHeight);ctx.drawImage(image,(512-image.naturalWidth*scale)/2,(512-image.naturalHeight*scale)/2,image.naturalWidth*scale,image.naturalHeight*scale);return canvas.toDataURL('image/png').split(',')[1]}
 function open(){const family=tenants.selected;if(!family)return;document.querySelectorAll('.family-install-dialog').forEach(d=>d.remove());const d=E('dialog',undefined,'family-install-dialog'),image=E('img');image.src=familyIconURL(family);image.alt=family.name;d.append(image,E('h2','تطبيق '+family.name),E('p','أيقونة مستقلة باسم عائلتك وشعارها، تفتح هذا الكيان مباشرة. الدخول إلى بيانات العائلة يتطلب حسابك وصلاحياتك.'));const platform=Capacitor.getPlatform();if(platform==='android'){d.append(B('إضافة أيقونة العائلة',()=>busy(null,async()=>{const result=await NativeFamilyBrand.pinFamilyShortcut({code:family.code,name:family.name,icon:await iconData(family)});toast(result.requested?'أكمل موافقة الإضافة من نافذة أندرويد.':'الإضافة غير متاحة في مشغل الشاشة الحالي.')}),'primary'))}else{
 const onFamilyPage=location.origin===FAMILY_SITE&&location.pathname==='/family/'+encodeURIComponent(family.code)+'/';
 if(!onFamilyPage){const a=E('a','فتح صفحة إضافة تطبيق العائلة','primary');a.href=familyAppURL(family)+'?install=1';if(platform==='ios'){a.target='_blank';a.rel='noopener'}d.append(a)}else{if(installEvent)d.append(B('تثبيت تطبيق العائلة',()=>busy(null,async()=>{const event=installEvent;installEvent=null;await event.prompt();const choice=await event.userChoice;toast(choice.outcome==='accepted'?'تم قبول طلب التثبيت.':'يمكنك الإضافة لاحقًا من القائمة.')}),'primary'));d.append(E('p','للآيفون: افتح هذه الصفحة في Safari، اضغط مشاركة، ثم «إضافة إلى الشاشة الرئيسية»، وفعّل «فتح كتطبيق ويب» ثم «إضافة».','install-steps'),E('p','لأندرويد من المتصفح: افتح قائمة المتصفح ثم «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».','install-steps'))}
 d.append(E('p','تظهر الأيقونة بعد موافقتك في النظام. قد تحتاج تسجيل الدخول أول مرة من الأيقونة الجديدة؛ لا تُنسخ جلسة الحساب إلى الرابط.','muted'))}
 d.append(B('لاحقًا',()=>{d.close();d.remove()},'secondary'));document.body.append(d);d.showModal();return d}
 function standalone(){return window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true}
 function offer(){nav.hidden=!state.user||!tenants.selected;if(nav.hidden)return;const family=tenants.selected,key='family-install-offered-'+family.id,explicit=new URLSearchParams(location.search).get('install')==='1';if(explicit){const url=new URL(location.href);url.searchParams.delete('install');history.replaceState(null,'',url.pathname+url.search+url.hash)}if(standalone()&&!explicit)return;if(!explicit&&localStorage.getItem(key))return;if(document.querySelector('dialog[open]'))return;localStorage.setItem(key,'1');open()}
 return{offer,open,reset(){nav.hidden=true;document.querySelectorAll('.family-install-dialog').forEach(d=>d.remove())}}
}
